use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

// Feature flags configuration
#[derive(Clone, Debug)]
pub struct FeatureFlags {
    flags: HashMap<String, bool>,
}

impl FeatureFlags {
    pub fn new() -> Self {
        let mut flags = HashMap::new();
        flags.insert("strict_encoding_validation".to_string(), true);
        flags.insert("allow_legacy_clients".to_string(), false);
        flags.insert("normalize_unicode_input".to_string(), true);
        FeatureFlags { flags }
    }

    pub fn is_enabled(&self, flag: &str) -> bool {
        *self.flags.get(flag).unwrap_or(&false)
    }

    pub fn set_flag(&mut self, flag: &str, value: bool) {
        self.flags.insert(flag.to_string(), value);
    }
}

// Path normalization layer
pub fn normalize_path_component(input: &[u8], flags: &FeatureFlags) -> Result<String, String> {
    // First pass: decode percent-encoded sequences
    let decoded = percent_decode(input)?;

    if flags.is_enabled("normalize_unicode_input") {
        // Apply NFC normalization for unicode consistency
        let normalized = unicode_normalize(&decoded);
        return validate_and_return(normalized, flags);
    }

    validate_and_return(decoded, flags)
}

fn percent_decode(input: &[u8]) -> Result<Vec<u8>, String> {
    let mut result = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        if input[i] == b'%' && i + 2 < input.len() {
            let high = hex_val(input[i + 1]).ok_or("Invalid hex")?;
            let low = hex_val(input[i + 2]).ok_or("Invalid hex")?;
            result.push((high << 4) | low);
            i += 3;
        } else {
            result.push(input[i]);
            i += 1;
        }
    }
    Ok(result)
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn unicode_normalize(input: &[u8]) -> Vec<u8> {
    // Simplified NFC-like normalization
    // Handles overlong UTF-8 sequences by re-encoding to shortest form
    let mut output = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        let byte = input[i];
        if byte & 0x80 == 0 {
            output.push(byte);
            i += 1;
        } else if byte & 0xE0 == 0xC0 && i + 1 < input.len() {
            let codepoint = ((byte as u32 & 0x1F) << 6) | (input[i+1] as u32 & 0x3F);
            // Re-encode to shortest form
            if codepoint < 0x80 {
                output.push(codepoint as u8);
            } else {
                output.push(byte);
                output.push(input[i+1]);
            }
            i += 2;
        } else if byte & 0xF0 == 0xE0 && i + 2 < input.len() {
            let codepoint = ((byte as u32 & 0x0F) << 12) 
                | ((input[i+1] as u32 & 0x3F) << 6) 
                | (input[i+2] as u32 & 0x3F);
            if codepoint < 0x80 {
                output.push(codepoint as u8);
            } else if codepoint < 0x800 {
                output.push(0xC0 | (codepoint >> 6) as u8);
                output.push(0x80 | (codepoint & 0x3F) as u8);
            } else {
                output.push(byte);
                output.push(input[i+1]);
                output.push(input[i+2]);
            }
            i += 3;
        } else {
            output.push(byte);
            i += 1;
        }
    }
    output
}

fn validate_and_return(data: Vec<u8>, flags: &FeatureFlags) -> Result<String, String> {
    let s = String::from_utf8(data).map_err(|e| format!("Invalid UTF-8: {}", e))?;

    if flags.is_enabled("strict_encoding_validation") {
        // Check for path traversal AFTER normalization
        if s.contains("../") || s.contains("..\\") {
            return Err("Path traversal detected".to_string());
        }
    }

    Ok(s)
}

// Request handler that resolves file paths
pub struct FileService {
    base_dir: String,
    flags: Arc<RwLock<FeatureFlags>>,
}

impl FileService {
    pub fn new(base_dir: String, flags: Arc<RwLock<FeatureFlags>>) -> Self {
        FileService { base_dir, flags }
    }

    pub async fn resolve_path(&self, raw_path: &[u8]) -> Result<String, String> {
        let flags = self.flags.read().await;

        // When legacy clients are allowed, we do a pre-decode pass
        // to handle double-encoded inputs from old client libraries
        let working_input = if flags.is_enabled("allow_legacy_clients") {
            percent_decode(raw_path)?
        } else {
            raw_path.to_vec()
        };

        let component = normalize_path_component(&working_input, &flags)?;

        let full_path = format!("{}/{}", self.base_dir, component);
        Ok(full_path)
    }

    // Admin endpoint to toggle feature flags at runtime
    pub async fn toggle_flag(&self, flag: &str, value: bool) {
        let mut flags = self.flags.write().await;
        flags.set_flag(flag, value);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_normal_path() {
        let flags = Arc::new(RwLock::new(FeatureFlags::new()));
        let svc = FileService::new("/srv/data".to_string(), flags);
        let result = svc.resolve_path(b"documents/report.pdf").await;
        assert_eq!(result.unwrap(), "/srv/data/documents/report.pdf");
    }

    #[tokio::test]
    async fn test_traversal_blocked() {
        let flags = Arc::new(RwLock::new(FeatureFlags::new()));
        let svc = FileService::new("/srv/data".to_string(), flags);
        let result = svc.resolve_path(b"../etc/passwd").await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_encoded_traversal_blocked() {
        let flags = Arc::new(RwLock::new(FeatureFlags::new()));
        let svc = FileService::new("/srv/data".to_string(), flags);
        // %2e%2e%2f = ../
        let result = svc.resolve_path(b"%2e%2e%2f etc/passwd").await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_legacy_double_encoded_traversal() {
        let flags = Arc::new(RwLock::new(FeatureFlags::new()));
        {
            let mut f = flags.write().await;
            f.set_flag("allow_legacy_clients", true);
        }
        let svc = FileService::new("/srv/data".to_string(), flags);
        // Double encoded: %252e%252e%252f -> %2e%2e%2f -> ../
        // This should be caught
        let result = svc.resolve_path(b"%252e%252e%252fetc/passwd").await;
        assert!(result.is_err());
    }
}
